options.styles:
.drill-m-card {
  background: #14171D;
  border-radius: 12px;
  padding: 20px 22px;
  border: 1.5px solid #232731;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 340px;
  box-sizing: border-box;
  box-shadow: 0 4px 14px rgba(0,0,0,0.3);
  transition: all 0.2s ease;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.drill-m-card.state-run {
  border-color: rgba(16, 185, 129, 0.45);
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.08);
}
.drill-m-card.state-alarm {
  border-color: rgba(239, 68, 68, 0.6);
  box-shadow: 0 4px 16px rgba(239, 68, 68, 0.15);
}
.drill-m-card.state-stop {
  border-color: rgba(245, 158, 11, 0.5);
  box-shadow: 0 4px 14px rgba(245, 158, 11, 0.08);
}
.drill-m-card.state-off {
  border-color: #334155;
}
.drill-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.drill-m-title {
  display: flex;
  align-items: center;
  gap: 10px;
}
.drill-m-name {
  font-size: 20px;
  font-weight: 800;
  color: #F8FAFC;
  text-decoration: none;
}
.drill-status-pill {
  font-size: 11.5px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.drill-status-pill::before {
  content: '';
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
}
.state-run .drill-status-pill { background: rgba(16, 185, 129, 0.18); color: #34D399; }
.state-run .drill-status-pill::before { background: #10B981; }
.state-alarm .drill-status-pill { background: rgba(239, 68, 68, 0.22); color: #F87171; }
.state-alarm .drill-status-pill::before { background: #EF4444; }
.state-stop .drill-status-pill { background: rgba(245, 158, 11, 0.2); color: #FBBF24; }
.state-stop .drill-status-pill::before { background: #F59E0B; }
.state-off .drill-status-pill { background: rgba(100, 116, 139, 0.2); color: #94A3B8; }
.state-off .drill-status-pill::before { background: #64748B; }

.drill-m-timeago {
  font-size: 12px;
  color: #94A3B8;
  font-weight: 500;
}
.drill-detail-table {
  display: flex;
  flex-direction: column;
  gap: 11px;
  font-size: 13.5px;
  margin-bottom: 18px;
}
.drill-detail-row {
  display: grid;
  grid-template-columns: 115px 1fr;
  align-items: baseline;
  gap: 8px;
}
.drill-detail-label {
  color: #94A3B8;
  font-weight: 500;
  font-size: 13px;
}
.drill-detail-val {
  color: #E2E8F0;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.drill-code-val {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  color: #34D399;
}
.drill-prog-val {
  font-family: 'JetBrains Mono', monospace;
  font-weight: 700;
  color: #38BDF8;
}
.drill-hole-val {
  color: #FBBF24;
  font-weight: 700;
}
.drill-tool-val {
  color: #F8FAFC;
  font-weight: 700;
}
.drill-msg-val {
  color: #38BDF8;
  font-size: 12px;
}
.drill-mid-pills {
  background: #0E1116;
  border: 1px solid #1E232D;
  border-radius: 8px;
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 14px;
}
.drill-pill-tag {
  font-size: 12px;
  color: #64748B;
  font-weight: 600;
}
.drill-pill-val-rpm, .drill-pill-val-feed {
  color: #34D399;
  font-weight: 700;
}
.drill-pill-sep {
  color: #334155;
}
.drill-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.drill-footer-last {
  font-size: 11.5px;
  color: #64748B;
}
.drill-copilot-link {
  font-size: 12px;
  font-weight: 600;
  color: #38BDF8;
  text-decoration: none;
  background: linear-gradient(180deg, rgba(14, 116, 144, 0.3) 0%, rgba(3, 105, 161, 0.4) 100%);
  border: 1px solid #0284C7;
  padding: 4px 12px;
  border-radius: 6px;
  box-shadow: 0 0 10px rgba(2, 132, 199, 0.2);
  transition: all 0.2s;
}
.drill-copilot-link:hover {
  background: #0284C7;
  color: #FFFFFF;
}

